import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { logout } from '../redux/slices/authSlice';
import './Navbar.css';

const Navbar = () => {
  const { user } = useSelector(state => state.auth);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  
  const handleLogout = () => {
    dispatch(logout());
    navigate('/login');
  };
  
  const toggleMobileMenu = () => {
    setMobileMenuOpen(!mobileMenuOpen);
  };
  
  const closeMobileMenu = () => {
    setMobileMenuOpen(false);
  };
  
  const isActive = (path) => {
    return location.pathname === path || location.pathname.startsWith(`${path}/`);
  };
  
  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/dashboard" className="navbar-logo" onClick={closeMobileMenu}>
          Mindfulness Therapy
        </Link>
        
        <div className="menu-icon" onClick={toggleMobileMenu}>
          <i className={mobileMenuOpen ? 'fas fa-times' : 'fas fa-bars'} />
        </div>
        
        <ul className={mobileMenuOpen ? 'nav-menu active' : 'nav-menu'}>
          <li className="nav-item">
            <Link 
              to="/dashboard" 
              className={`nav-link ${isActive('/dashboard') ? 'active' : ''}`}
              onClick={closeMobileMenu}
            >
              Dashboard
            </Link>
          </li>
          
          <li className="nav-item">
            <Link 
              to="/therapy" 
              className={`nav-link ${isActive('/therapy') ? 'active' : ''}`}
              onClick={closeMobileMenu}
            >
              Therapy
            </Link>
          </li>
          
          <li className="nav-item">
            <Link 
              to="/journal" 
              className={`nav-link ${isActive('/journal') ? 'active' : ''}`}
              onClick={closeMobileMenu}
            >
              Journal
            </Link>
          </li>
          
          <li className="nav-item">
            <Link 
              to="/mood-tracker" 
              className={`nav-link ${isActive('/mood-tracker') || isActive('/mood-history') ? 'active' : ''}`}
              onClick={closeMobileMenu}
            >
              Mood Tracker
            </Link>
          </li>
          
          <li className="nav-item dropdown">
            <div 
              className={`nav-link user-menu ${isActive('/profile') ? 'active' : ''}`}
            >
              <span className="user-name">{user?.username || 'User'}</span>
              <div className="dropdown-content">
                <Link 
                  to="/profile" 
                  className="dropdown-item"
                  onClick={closeMobileMenu}
                >
                  Profile
                </Link>
                <button 
                  onClick={() => {
                    closeMobileMenu();
                    handleLogout();
                  }} 
                  className="dropdown-item logout-btn"
                >
                  Logout
                </button>
              </div>
            </div>
          </li>
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
